<template>
 <section class="terminal-page" aria-label="分析终端">
  <header class="terminal-header"><div class="eyebrow">WONDERTRADER / RESEARCH DESK</div><div class="terminal-title"><h1>分析终端</h1><p>看数据、检验假设，再交给原生交易流程。</p><el-tag effect="plain">{{loading?'正在读取':catalog.can_edit?'研究模式':'游客 · 只读'}}</el-tag></div><nav class="terminal-tabs" aria-label="分析终端栏目"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" :aria-pressed="tab===t.id" @click="setTab(t.id)">{{t.name}}</button></nav></header>
  <div class="terminal-body" v-loading="loading">
   <el-alert v-if="error" :title="error" type="error" :closable="false" style="margin-bottom:14px"/>
   <template v-if="tab==='analytics'">
    <div class="terminal-grid">
     <section class="terminal-panel"><header><strong>选择分析工具</strong><small>{{catalog.tools?.length||0}} TOOLS</small></header><div class="terminal-panel-body"><el-select v-model="toolId" filterable aria-label="分析工具" @change="selectTool"><el-option-group v-for="group in toolGroups" :key="group" :label="group"><el-option v-for="t in catalog.tools.filter(t=>t.group===group)" :key="t.id" :label="t.name" :value="t.id"/></el-option-group></el-select><p class="note">{{tool?.note}}</p><el-form v-if="tool" label-position="top"><el-form-item v-for="f in tool.fields" :key="f.key" :label="f.label"><el-input v-if="f.kind==='text'" v-model="params[f.key]" type="textarea" :rows="f.key==='matrix'?6:3" :aria-label="f.label"/><el-select v-else-if="f.kind==='side'" v-model="params[f.key]" :aria-label="f.label"><el-option label="看涨" value="call"/><el-option label="看跌" value="put"/></el-select><el-select v-else-if="f.kind==='objective'" v-model="params[f.key]" :aria-label="f.label"><el-option label="最小方差" value="min_variance"/><el-option label="最大夏普（样本内）" value="max_sharpe"/></el-select><el-input v-else-if="f.kind==='date'" v-model="params[f.key]" :aria-label="f.label"/><el-input-number v-else v-model="params[f.key]" :controls="false" :aria-label="f.label"/></el-form-item></el-form><el-button type="primary" :disabled="!catalog.can_edit" :loading="busy" @click="runCalculation">计算</el-button><p class="note">结果只用于分析，不会下单或修改组合。</p></div></section>
     <section class="terminal-panel"><header><strong>{{tool?.name||'分析结果'}}</strong><small>{{analysis?.engine||tool?.engine}}</small></header><template v-if="analysis"><div v-if="analysis.metrics" class="metric-grid"><div v-for="(v,k) in analysis.metrics" :key="k" class="metric"><span>{{k}}</span><strong>{{formatMetric(k,v)}}</strong></div></div><TerminalChart v-if="analysis.series?.length" :series="analysis.series"/><div class="terminal-panel-body"><el-table v-if="analysis.rows?.length" :data="analysis.rows" max-height="430"><el-table-column v-for="key in rowKeys(analysis.rows)" :key="key" :prop="key" :label="columnName(key)" min-width="120"><template #default="{row}">{{formatValue(row[key])}}</template></el-table-column></el-table><p class="note">{{analysis.note||tool?.note}}</p></div></template><div v-else class="empty-message"><strong>让假设变成可检查的数字</strong><p>选择工具并填写参数，结果和曲线会显示在这里。</p><router-link to="/monitor">查看 WT 账户真实收益 →</router-link></div></section>
    </div>
   </template>
   <template v-else-if="tab==='data'">
    <div class="terminal-grid"><section class="terminal-panel"><header><strong>公开数据</strong><small>ON DEMAND</small></header><div class="terminal-panel-body"><el-select v-model="datasetId" filterable aria-label="数据集" @change="loadDataset(false)"><el-option v-for="d in catalog.datasets" :key="d.id" :value="d.id" :label="d.name+' · '+d.frequency"/></el-select><p class="note">只在点击加载时访问供应方。失败时保留带时间戳的旧数据。</p><el-button :disabled="!catalog.can_edit" :loading="busy" @click="loadDataset(true)">加载 / 更新</el-button><p class="note">{{selectedDataset?.unit}} · {{selectedDataset?.frequency}}</p><router-link to="/history">管理 WT 历史与研究数据 →</router-link></div></section>
     <section class="terminal-panel"><header><strong>{{selectedDataset?.name}}</strong><small>{{dataset?.source||'DATA'}}</small></header><div class="terminal-panel-body"><div class="terminal-status"><el-tag v-if="dataset" :type="dataset.stale?'warning':dataset.status==='ready'?'success':'info'">{{datasetStatus(dataset)}}</el-tag><span v-if="dataset?.fetched_at">抓取 {{stamp(dataset.fetched_at)}}</span><a v-if="safeUrl(dataset?.source_url)" :href="safeUrl(dataset.source_url)" target="_blank" rel="noopener noreferrer">来源 ↗</a></div><el-alert v-if="dataset?.error" :title="dataset.error" type="warning" :closable="false"/><TerminalChart v-if="dataset?.series?.length" :series="dataset.series"/><el-table v-if="dataset?.rows?.length" :data="dataset.rows" max-height="360"><el-table-column v-for="key in rowKeys(dataset.rows)" :key="key" :prop="key" :label="columnName(key)" min-width="135"><template #default="{row}">{{formatValue(row[key])}}</template></el-table-column></el-table><p v-for="link in dataset?.links||[]" :key="link.label" class="note">{{link.label}}：{{link.value}} · 来源索引时间 {{link.source_updated_at||'未提供'}}</p><p class="note">{{dataset?.note||'尚未加载。频率与公布时间核对后，数据才能进入因子验证。'}}</p></div></section>
    </div><div class="terminal-source-list"><article v-for="s in catalog.sources" :key="s.id" class="terminal-source"><strong><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.name}} ↗</a><el-tag size="small" :type="s.configured?'success':'info'">{{s.configured?'可请求':'未启用'}}</el-tag></strong><small>{{s.access}}</small><p class="note">{{s.note}}</p></article></div>
   </template>
   <template v-else-if="tab==='ai'">
    <div class="terminal-grid"><section class="terminal-panel"><header><strong>AI 研究助手</strong><small>CODEX BRIDGE</small></header><div class="terminal-panel-body"><div class="terminal-status"><el-tag :type="budget.remaining?'info':'warning'">共享额度 {{budget.used||0}} / {{budget.limit||12}}</el-tag><span>{{budget.date}}</span></div><el-form label-position="top"><el-form-item label="研究视角"><el-select v-model="roleId" aria-label="研究视角"><el-option-group v-for="group in roleGroups" :key="group" :label="group"><el-option v-for="role in catalog.roles.filter(r=>r.group===group)" :key="role.id" :value="role.id" :label="role.name"/></el-option-group></el-select></el-form-item><el-form-item label="已有原文资料（最多 3 份）"><el-select v-model="reportIds" multiple filterable :multiple-limit="3" aria-label="AI 参考资料"><el-option v-for="r in reports" :key="r.id" :value="r.id" :label="r.title"/></el-select></el-form-item><el-form-item label="具体研究问题"><el-input v-model="question" type="textarea" :rows="5" maxlength="4000" placeholder="例如：这个因子需要哪些数据？有哪些反例？如何用现有样本验证？" aria-label="研究问题"/></el-form-item></el-form><el-button type="primary" :disabled="!catalog.can_edit||!budget.remaining||!reportIds.length||question.trim().length<10" :loading="busy" @click="startResearch">开始研究</el-button><p class="note">每次只运行一个视角。与 RD-Agent 共用每日上限，不自动展开多智能体讨论。</p></div><div class="terminal-list"><button v-for="job in jobs" :key="job.id" :class="{active:currentJob?.id===job.id}" @click="currentJob=job">{{job.question.slice(0,65)}}<small>{{job.role_name}} · {{jobStatus(job.status)}} · {{stamp(job.created_at)}}</small></button></div></section>
     <section class="terminal-panel"><header><strong>{{currentJob?.role_name||'有原文的研究'}}</strong><el-button text @click="loadJobs">刷新结果</el-button></header><div v-if="currentJob" class="terminal-panel-body"><el-alert v-if="currentJob.error" :title="currentJob.error" type="warning" :closable="false"/><p class="note">{{jobStatus(currentJob.status)}} · {{currentJob.question}}</p><div v-if="currentJob.answer" class="terminal-ai-answer"><section v-for="(label,key) in answerLabels" :key="key"><h3>{{label}}</h3><p>{{currentJob.answer[key]}}</p></section><div class="terminal-actions" style="margin-top:16px"><el-button :disabled="!catalog.can_edit||promoted.has(currentJob.id)" @click="createCandidate">{{promoted.has(currentJob.id)?'已建立研究项目':'建立研究候选'}}</el-button><router-link to="/research">进入研究与验证 →</router-link></div><p class="note">候选保留原文引用和 AI 假设。因子、成本与原生回测仍走现有流程。</p></div></div><div v-else class="empty-message"><strong>先问一个具体问题</strong><p>原文、反例、数据需求与验证方法会分别保存。</p></div></section>
    </div>
   </template>
   <template v-else-if="tab==='automation'">
    <section class="terminal-panel"><header><strong>现行因子流水线</strong><router-link :to="{path:'/research',query:{section:'factors'}}">查看任务与拒绝原因 →</router-link></header><div class="terminal-panel-body"><div class="terminal-pipeline"><div v-for="(n,i) in pipeline" :key="n.name"><b>0{{i+1}}</b><strong>{{n.name}}</strong><small>{{n.detail}}</small></div></div><p class="note">40 个对齐原生交易日、20 个独立前向交易日、60 笔平仓等准入继续由服务器检查。流程画布不能跳过这些检查。</p><div class="terminal-actions"><el-tag v-for="p in catalog.pipeline" :key="p.id" effect="plain">{{p.name}} {{p.count}}</el-tag><router-link to="/schedule">调度中心 →</router-link></div></div></section>
    <section class="terminal-panel" style="margin-top:14px"><header><strong>轻量分析流程</strong><small>DATA → RETURNS → RISK → RESULT</small></header><div class="terminal-panel-body"><FlowCanvas :request="request" :datasets="catalog.datasets||[]" :can-edit="catalog.can_edit"/></div></section>
    <section class="terminal-panel" style="margin-top:14px"><header><strong>MCP 与 Quant Lab</strong><small>复用现有引擎</small></header><div class="terminal-panel-body"><p class="note">MCP 提供本机工具目录、研究计算和公开数据缓存读取。不会暴露下单、Shell 或上线工具。</p><div class="terminal-actions"><router-link to="/research">RD-Agent / KunQuant / 因子检验 →</router-link><router-link to="/backtest">WT 原生策略回测 →</router-link><router-link to="/strategies">版本与策略库 →</router-link></div><p class="note">机器学习和强化学习的训练结果仍须转换为可复现候选。强化学习训练尚未接入，当前主机不启动大规模训练。</p></div></section>
   </template>
   <template v-else-if="tab==='intelligence'">
    <div class="terminal-actions" style="margin-bottom:14px"><el-button @click="loadIntelligence">刷新已采集资料</el-button><el-button :disabled="!catalog.can_edit" :loading="busy" @click="loadNews">加载航运新闻</el-button><el-button :disabled="!catalog.can_edit" :loading="busy" @click="loadMaritime">加载航道资料</el-button><el-tag effect="plain">实时 AIS 船位：未配置密钥</el-tag></div>
    <div class="terminal-news"><section class="terminal-panel"><header><strong>{{news?'航运与能源新闻':'已采集资料中的事件'}}</strong><small>{{news?.fetched_at?stamp(news.fetched_at):'SOURCE FIRST'}}</small></header><el-alert v-if="news?.error" :title="news.error" type="warning" :closable="false"/><div v-for="r in articles" :key="r.id||r.url" class="terminal-article"><h3><a v-if="safeUrl(r.url)" :href="safeUrl(r.url)" target="_blank" rel="noopener noreferrer">{{r.title}} ↗</a><span v-else>{{r.title}}</span></h3><small>{{r.time||'未提供发布时间'}} · {{r.domain||r.themes?.join(' / ')}}</small></div><div v-if="!articles.length" class="empty-message">没有可展示的已采集事件</div></section><div><section class="terminal-panel"><header><strong>资料与主题关系</strong><small>MENTIONS</small></header><TerminalChart :graph="mentionGraph" label="资料主题提及图"/><div class="terminal-panel-body"><p class="note">{{intel?.note}}</p><el-button text @click="setTab('ai');roleId='geopolitics'">带原文做地缘分析 →</el-button></div></section><section class="terminal-panel" style="margin-top:14px"><header><strong>海运观察</strong><a href="https://portwatch.imf.org/" target="_blank" rel="noopener noreferrer">IMF PortWatch ↗</a></header><div class="terminal-panel-body"><p class="note">航道、新闻和实时船位分开展示。公开航道资料不代表船舶正在通过。</p><el-alert v-if="maritime?.error" :title="maritime.error" type="warning" :closable="false"/><el-table v-if="maritime?.rows?.length" :data="maritime.rows" max-height="300"><el-table-column v-for="key in rowKeys(maritime.rows)" :key="key" :prop="key" :label="columnName(key)" min-width="130"/></el-table><p v-else class="note">点击“加载航道资料”读取公开数据。</p></div></section></div></div>
   </template>
  </div>
 </section>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import TerminalChart from './TerminalChart.vue'
import FlowCanvas from './FlowCanvas.vue'
import {formatValue,formatMetric} from './format.js'
const route=useRoute(),router=useRouter()
const tabs=[{id:'analytics',name:'分析工具'},{id:'data',name:'数据中心'},{id:'ai',name:'AI 研究'},{id:'automation',name:'自动化'},{id:'intelligence',name:'全球情报'}]
const tab=ref(tabs.some(t=>t.id===route.query.tab)?route.query.tab:'analytics'),catalog=ref({tools:[],roles:[],sources:[],datasets:[],can_edit:false}),loading=ref(false),busy=ref(false),error=ref('')
const toolId=ref('black76'),params=ref({}),analysis=ref(null),datasetId=ref('sp500'),dataset=ref(null),roleId=ref('factor'),question=ref(''),reportIds=ref([]),reports=ref([]),jobs=ref([]),currentJob=ref(null),budget=ref({}),promoted=ref(new Set()),intel=ref(null),news=ref(null),maritime=ref(null)
const tool=computed(()=>catalog.value.tools.find(t=>t.id===toolId.value)),toolGroups=computed(()=>[...new Set(catalog.value.tools.map(t=>t.group))]),roleGroups=computed(()=>[...new Set(catalog.value.roles.map(t=>t.group))]),selectedDataset=computed(()=>catalog.value.datasets.find(d=>d.id===datasetId.value))
const answerLabels={conclusion:'主要判断',facts:'原文事实',hypothesis:'可检验假设',counterexample:'反例与替代解释',data_needed:'数据需求',validation:'验证步骤',sources:'原文引用'}
const pipeline=[{name:'原文与假设',detail:'资料采集 · 单点假设'},{name:'数据与计算',detail:'时点校验 · KunQuant'},{name:'固定检验',detail:'Optuna · IC · 去重'},{name:'原生收益',detail:'WT · 统一成本 · 全候选'},{name:'准入与应用',detail:'DSR/PBO · 前向 · 风控'},{name:'持续复盘',detail:'衰减 · 运行故障 · 退役'}]
const articles=computed(()=>news.value?.status==='ready'?news.value.rows:(intel.value?.articles||[]))
const mentionGraph=computed(()=>({nodes:[...(intel.value?.themes||[]).map(t=>({id:t.id,name:t.name,symbolSize:24+Math.min(t.count,20)})),...(intel.value?.articles||[]).slice(0,12).map((r,i)=>({id:r.id,name:String(i+1),symbolSize:10}))],edges:(intel.value?.edges||[]).filter(e=>(intel.value?.articles||[]).slice(0,12).some(r=>r.id===e.source))}))
async function request(action,body={}){const response=await fetch('/mgr/research/terminal/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok||value.result!==0)throw new Error(value.message||'分析请求失败');return value}
async function researchRequest(action,body={}){const response=await fetch('/mgr/research/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok||value.result!==0)throw new Error(value.message||'研究请求失败');return value}
async function perform(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function selectTool(){params.value=Object.fromEntries((tool.value?.fields||[]).map(f=>[f.key,f.default]));analysis.value=null}
async function runCalculation(){await perform(async()=>{analysis.value=await request('calculate',{tool:toolId.value,params:params.value})})}
async function loadDataset(refresh){await perform(async()=>{dataset.value=await request('data',{dataset:datasetId.value,refresh})})}
function stamp(value){return value?new Date(value*1000).toLocaleString('zh-CN',{hour12:false}):'—'}
function safeUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function rowKeys(rows){return Object.keys(rows?.[0]||{}).filter(k=>!['url','OBJECTID','ObjectId','objectid'].includes(k)).slice(0,7)}
function columnName(key){return {asset:'资产',weight:'权重',year:'年',cashflow:'现金流',present_value:'现值',discount:'折现因子',zero_rate:'零息利率',symbol:'标的',last:'最新价',bid:'买一',ask:'卖一',volume_24h:'24h 成交量',title:'标题',time:'时间',country:'来源国家',domain:'来源站点',longitude:'经度',latitude:'纬度'}[key]||key}
function datasetStatus(d){return d.stale?'旧缓存':({ready:d.cached?'缓存有效':'已获取',unavailable:'暂不可用',not_loaded:'未加载'}[d.status]||d.status)}
function jobStatus(s){return {running:'研究中',completed:'已完成',failed:'失败',interrupted:'已中断'}[s]||s}
async function loadJobs(){try{const data=await request('research_list');jobs.value=data.jobs;budget.value=data.budget;if(currentJob.value)currentJob.value=jobs.value.find(j=>j.id===currentJob.value.id)||currentJob.value;else currentJob.value=jobs.value[0]||null}catch(e){error.value=e.message}}
async function loadReports(){if(!catalog.value.can_edit)return;const data=await researchRequest('list',{include_catalog:false});reports.value=data.reports||[]}
async function startResearch(){await perform(async()=>{const data=await request('research_start',{role:roleId.value,question:question.value,report_ids:reportIds.value});currentJob.value=data.job;await loadJobs()})}
async function createCandidate(){await perform(async()=>{const j=currentJob.value;await researchRequest('project_save',{title:(j.role_name+'：'+j.question).slice(0,170),report_id:j.report_ids[0],kind:'timeseries',hypothesis:j.answer.hypothesis,formula:'',notes:'AI 研究记录 '+j.id+'\n'+Object.entries(answerLabels).map(([key,label])=>label+'：\n'+j.answer[key]).join('\n\n')});promoted.value.add(j.id);ElMessage.success('研究项目已建立，原文和验证建议已保留')})}
async function loadIntelligence(){try{intel.value=await request('intelligence')}catch(e){error.value=e.message}}
async function loadNews(){await perform(async()=>{news.value=await request('data',{dataset:'shipping_news',refresh:true})})}
async function loadMaritime(){await perform(async()=>{maritime.value=await request('data',{dataset:'chokepoints',refresh:true})})}
async function setTab(id){tab.value=id;router.replace({query:{...route.query,tab:id}});error.value='';try{if(id==='ai'){await loadReports();await loadJobs()}if(id==='intelligence')await loadIntelligence();if(id==='data')await loadDataset(false)}catch(e){error.value=e.message}}
let poll
onMounted(async()=>{loading.value=true;try{catalog.value=await request('catalog');budget.value=catalog.value.budget;selectTool();await setTab(tab.value)}catch(e){error.value=e.message}finally{loading.value=false}poll=setInterval(()=>{if(!document.hidden&&tab.value==='ai'&&jobs.value.some(j=>j.status==='running'))loadJobs()},5000)})
onBeforeUnmount(()=>clearInterval(poll))
</script>
